'use strict';
const $=id=>document.getElementById(id),game=document.querySelector('.game');
const ROWS=9,COLS=6,COUNT=54,MINE_COUNT=10;
const sprites={cube:[[0,0],[50,0]],gold:[100,0],green:[0,100],bomb:[50,100],empty:[100,100]};
let paused=false,roundCounter=0,roundId='';
let renderSnapshot=[],motionOrigin=0;
const reducedMotion=window.matchMedia?.('(prefers-reduced-motion: reduce)');
function animateNode(node,frames,options={}){if(!node?.animate||reducedMotion?.matches||paused)return;return node.animate(frames,{duration:360,easing:'cubic-bezier(.2,.8,.2,1)',...options})}
function clearEffects(){document.querySelectorAll('.fx-layer').forEach(n=>n.remove())}
function particles(target,celebrate=false){if(reducedMotion?.matches||paused||!target?.append)return;const layer=document.createElement('div');layer.className='fx-layer';layer.setAttribute('aria-hidden','true');target.append(layer);const green=!!target.querySelector?.('.art-green');const count=celebrate?22:8;for(let n=0;n<count;n++){const dot=document.createElement('i');dot.className=celebrate?'confetti':'spark';const angle=(n/count)*Math.PI*2,spread=celebrate?105:27;dot.style.left=celebrate?(12+(n*37)%76)+'%':'50%';dot.style.top=celebrate?'12%':'50%';dot.style.background=green?(n%2?'#4de3a0':'#c1ffdf'):(n%3===0?'#fff3bd':n%3===1?'#ffb327':'#ffe08a');layer.append(dot);const anim=animateNode(dot,[{transform:'translate(0,0) rotate(0deg) scale(1)',opacity:1},{transform:`translate(${Math.cos(angle)*spread}px,${celebrate?180+(n%5)*20:Math.sin(angle)*spread}px) rotate(${(n%2?1:-1)*180}deg) scale(.3)`,opacity:0}],{duration:celebrate?1000:480,delay:celebrate?n*12:0,easing:'cubic-bezier(.15,.6,.4,1)'});if(anim)anim.finished.then(()=>{dot.remove();if(!layer.children.length)layer.remove()}).catch(()=>layer.remove());else layer.remove()}}
function resultMotion(won){const dialog=$('dialog');animateNode(dialog,won?[{transform:'translateY(12px) scale(.94)',opacity:.65,boxShadow:'0 0 0 #ffb32700'},{transform:'translateY(0) scale(1)',opacity:1,boxShadow:'0 0 45px #ffb32740'},{transform:'translateY(0) scale(1)',opacity:1,boxShadow:'0 20px 100px #000'}]:[{transform:'translateX(0)'},{transform:'translateX(-5px)'},{transform:'translateX(5px)'},{transform:'translateX(-3px)'},{transform:'translateX(0)'}],{duration:won?600:300});if(won)particles(dialog,true)}
function platformEvent(type,extra={}){if(window.parent!==window)window.parent.postMessage({type,roundId,...extra},location.origin)}
function returnToLobby(){mineAudio.leave();if(window.parent!==window){paused=true;platformEvent('game-return')}else location.href='./'}
window.addEventListener('message',e=>{if(e.origin===location.origin&&e.source===window.parent&&e.data?.type==='platform-pause'){paused=!!e.data.paused;game.classList.toggle('motion-paused',paused);if(paused){mineAudio.leave();document.getAnimations?.().forEach(a=>a.cancel())}}});
let state='tutorial',step=0,board=[],started=false,mode='reveal',seconds=0,reward=0,claimed=false,tutorialFlag=false,toastTimeout;
function neighbors(i){let a=[];for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++){let y=Math.floor(i/COLS)+dy,x=i%COLS+dx;if((dx||dy)&&y>=0&&y<ROWS&&x>=0&&x<COLS)a.push(y*COLS+x)}return a}
function art(type,i,value=type==='gold'?1:type==='green'?2:null){const p=type==='cube'?sprites.cube[(i+Math.floor(i/6))%2]:sprites[type];return `<span class="art art-${type}" aria-hidden="true" style="background-position:${p[0]}% ${p[1]}%;--coin-delay:${(i%11)*.61}s">${value?`<span class="coin-value">${value}</span>`:''}</span>`}
let lastInteraction=Date.now(),lastIdleMotion=0;
function clearIdleHint(){document.querySelectorAll('.idle-hint').forEach(n=>n.classList.remove('idle-hint'))}
function resetIdle(){lastInteraction=Date.now();clearIdleHint()}
function updateIdle(){if(paused||document.hidden||reducedMotion?.matches||$('dialog').open)return;const waiting=state==='tutorial'||(state==='playing'&&!started);if(!waiting)return;const elapsed=Date.now()-lastInteraction;if(elapsed<3000)return;if(state==='playing'&&mode==='reveal'){const index=board.findIndex((c,i)=>i>=14&&!c.flagged);if(index>=0)$('board').children[index]?.classList.add('idle-hint');$('description').textContent='点一个方块，试试手气。首次点击安全。'}if(Date.now()-lastIdleMotion>6000){lastIdleMotion=Date.now();[1,35].forEach((i,k)=>animateNode($('board').children[i]?.querySelector('.art-cube'),[{transform:'translateY(0)'},{transform:'translateY(-2px)',offset:.5},{transform:'translateY(0)'}],{duration:1500,delay:k*280,easing:'ease-in-out'}))}}
game.addEventListener('pointerdown',()=>{resetIdle();mineAudio.unlock()});game.addEventListener('keydown',()=>{resetIdle();mineAudio.unlock()});document.addEventListener('visibilitychange',()=>{if(document.hidden)mineAudio.stop()});$('mine-sound').onclick=()=>{const on=mineAudio.toggle();$('mine-sound').setAttribute('aria-pressed',on);$('mine-sound').setAttribute('aria-label',on?'关闭音效':'开启音效');$('mine-sound').textContent=on?'♪':'♩'};
function tutorial(){resetIdle();game.classList.add('is-waiting');clearEffects();renderSnapshot=[];state='tutorial';step=0;tutorialFlag=false;game.classList.remove('playing');$('stats').hidden=true;$('modes').hidden=true;$('notice').hidden=true;$('title').textContent='认识棋盘';$('description').innerHTML="金币上的数字代表周围的地雷数量。<br class='wide'> 确定是地雷的方块，可以用旗帜标记。";$('primary').textContent='下一步';$('secondary').textContent='跳过教程';renderTutorial()}
function renderTutorial(){const revealed={3:'gold',4:'empty',5:'empty',8:'bomb',9:'gold',10:'empty',11:'empty',13:'green',14:'gold',15:'gold',16:'empty',17:'empty',19:'gold',20:'empty',21:'empty',22:'empty',23:'empty',25:'green',26:'green',27:'green',28:'green',29:'gold'};$('board').innerHTML=Array.from({length:COUNT},(_,i)=>`<button class="cell" data-i="${i}" aria-label="Row ${Math.floor(i/6)+1}, column ${i%6+1}, ${i===8?'tutorial mine':revealed[i]||'unopened block'}">${art(revealed[i]||'cube',i)}${i===8&&tutorialFlag?'<span class="flagMark">⚑</span>':''}</button>`).join('');if(tutorialFlag)animateNode($('board').querySelector('.flagMark'),[{transform:'translateY(-10px) scale(.5)',opacity:0},{transform:'translateY(0) scale(1)',opacity:1}],{duration:300})}
function setMode(m){mode=m;for(const x of ['flag','reveal']){$(x).classList.toggle('active',x===m);$(x).setAttribute('aria-pressed',String(x===m))}}
function start(){mineAudio.stop();resetIdle();game.classList.add('is-waiting');clearEffects();renderSnapshot=[];paused=false;game.classList.remove('motion-paused');roundId=String(++roundCounter);state='playing';started=false;seconds=0;reward=0;claimed=false;board=Array.from({length:COUNT},()=>({mine:false,revealed:false,flagged:false,n:0}));game.classList.add('playing');$('stats').hidden=false;$('modes').hidden=false;$('notice').hidden=false;$('title').textContent='找到你的好运';$('description').textContent='揭开金币，标记地雷，清空棋盘。';$('primary').textContent='新的一局';$('secondary').textContent='玩法说明';setMode('reveal');$('dialog').close();render()}
function seed(first){clearIdleHint();game.classList.remove('is-waiting');$('description').textContent='揭开金币，标记地雷，清空棋盘。';const safe=new Set([first,...neighbors(first)]),pool=Array.from({length:COUNT},(_,i)=>i).filter(i=>!safe.has(i));for(let n=0;n<MINE_COUNT;n++){const j=n+Math.floor(Math.random()*(pool.length-n));[pool[n],pool[j]]=[pool[j],pool[n]];board[pool[n]].mine=true}board.forEach((c,i)=>c.n=neighbors(i).filter(k=>board[k].mine).length);started=true}
function render(){
 const root=$('board'),fresh=renderSnapshot.length!==COUNT;let flags=0,coins=0,newReveals=[];
 if(fresh){root.replaceChildren();for(let i=0;i<COUNT;i++){const button=document.createElement('button');button.className='cell';button.dataset.i=i;root.append(button)}}
 board.forEach((c,i)=>{if(c.flagged)flags++;if(c.revealed&&!c.mine)coins++;const key=c.revealed?`open:${c.mine}:${c.n}`:`closed:${c.flagged}`,changed=renderSnapshot[i]!==key,node=root.children[i];node.disabled=state!=='playing';
 if(changed){const type=c.revealed?(c.mine?'bomb':c.n===0?'empty':c.n===1?'gold':'green'):'cube';node.innerHTML=art(type,i,c.revealed&&!c.mine?c.n:null)+(c.flagged&&!c.revealed?'<span class="flagMark">⚑</span>':'');node.setAttribute('aria-label',`第 ${Math.floor(i/6)+1} 行，第 ${i%6+1} 列，${c.flagged?'已插旗':c.revealed?(c.mine?'地雷':c.n+' 颗相邻地雷'):'未揭开'}`);
 if(fresh){animateNode(node,[{transform:'translateY(8px) scale(.85)',opacity:0},{transform:'translateY(0) scale(1)',opacity:1}],{duration:320,delay:Math.floor(i/6)*20+i%6*9})}
 else if(c.revealed&&!c.mine){newReveals.push(i);const delay=Math.min(180,(Math.abs(i%6-motionOrigin%6)+Math.abs(Math.floor(i/6)-Math.floor(motionOrigin/6)))*24);animateNode(node,[{transform:'scale(.72) rotateY(-70deg)',filter:'brightness(1.6)'},{transform:'scale(1.12) rotateY(0deg)',filter:'brightness(1.3)',offset:.6},{transform:'scale(1) rotateY(0deg)',filter:'brightness(1)'}],{duration:380,delay})}
 else if(c.flagged){animateNode(node.querySelector('.flagMark'),[{transform:'translateY(-12px) scale(.4)',opacity:0},{transform:'translateY(2px) scale(1.18)',opacity:1,offset:.65},{transform:'translateY(0) scale(1)',opacity:1}],{duration:320})}
 else{animateNode(node,[{transform:'scale(.88)'},{transform:'scale(1.04)',offset:.65},{transform:'scale(1)'}],{duration:220})}
 }renderSnapshot[i]=key;
 });
 $('mines').textContent=MINE_COUNT-flags;$('coins').textContent=state==='lost'?0:coins*10;$('timer').textContent=`${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;
 if(newReveals.length){animateNode($('coins'),[{transform:'scale(1)',color:'#ffbc46'},{transform:'scale(1.25)',color:'#fff3a5',offset:.4},{transform:'scale(1)',color:'#ffbc46'}]);particles(root.children[motionOrigin]);}
}
function act(i,flag=false){if(state!=='playing'||!Number.isInteger(i)||i<0||i>=COUNT)return;const c=board[i];if(c.revealed)return;motionOrigin=i;if(flag){if(!c.flagged&&board.filter(x=>x.flagged).length>=MINE_COUNT){toast('10 面旗帜已用完，请先取消一处标记。');return}c.flagged=!c.flagged;mineAudio.flag();render();return}if(c.flagged)return;if(!started)seed(i);if(c.mine){mineAudio.lose();c.revealed=true;state='lost';reward=0;platformEvent('game-finished',{won:false,seconds});board.forEach(c=>{if(c.mine)c.revealed=true});render();$('title').textContent='踩到地雷了';showDialog('差一点点，再试一次','本局踩到了地雷，得分已归零。重新开局试试，第一次点击始终安全。',[['再玩一局',start],['查看棋盘',()=>{}],['返回大厅',returnToLobby]]);resultMotion(false);return}mineAudio.reveal(c.n>=2);const queue=[i];while(queue.length){const k=queue.pop(),cell=board[k];if(cell.revealed||cell.flagged||cell.mine)continue;cell.revealed=true;if(cell.n===0)queue.push(...neighbors(k))}if(board.every(c=>c.mine||c.revealed)){state='won';platformEvent('game-finished',{won:true,seconds});reward=440;$('title').textContent='成功通关！';showDialog('漂亮的一局',`已揭开全部 44 个安全方块。\n你的通关奖励：${reward} 模拟积分。`,[['领取模拟积分',claim],['查看棋盘',()=>{}]]);$('primary').textContent='领取积分'}render();if(state==='won'){mineAudio.win();resultMotion(true)}}
function claim(){if(state!=='won'||claimed)return;claimed=true;mineAudio.win();platformEvent('game-reward');showDialog('积分已领取',`本局已领取 ${reward} 模拟积分。\n可在大厅的「奖励」中查看。积分不具有货币价值。`,[['再玩一局',start],['返回大厅',returnToLobby]]);$('primary').textContent='新的一局';resultMotion(true)}
function showDialog(title,body,actions){clearEffects();$('dialogTitle').textContent=title;$('dialogText').textContent=body;$('dialogActions').replaceChildren();actions.forEach(([label,fn])=>{const b=document.createElement('button');b.textContent=label;b.onclick=()=>{$('dialog').close();fn()};$('dialogActions').append(b)});if(!$('dialog').open)$('dialog').showModal()}
function toast(text){clearTimeout(toastTimeout);$('toast').textContent=text;$('toast').classList.add('show');toastTimeout=setTimeout(()=>$('toast').classList.remove('show'),2400)}
function newRound(){if(state==='playing'&&started){showDialog('开始新的一局？','当前棋盘将重置。',[['新的一局',start],['继续游戏',()=>{}]])}else start()}
$('board').onclick=e=>{const b=e.target.closest('[data-i]');if(!b)return;const i=Number(b.dataset.i);if(state==='tutorial'){if(i===8){tutorialFlag=!tutorialFlag;renderTutorial();toast(tutorialFlag?'已插旗，这里是一颗地雷。':'已取消标记。')}else toast('金币数字代表周围地雷的数量。');return}act(i,mode==='flag')};$('board').oncontextmenu=e=>{const b=e.target.closest('[data-i]');if(b){e.preventDefault();act(Number(b.dataset.i),true)}};
$('primary').onclick=()=>{if(state==='tutorial'){if(step++===0){tutorialFlag=true;renderTutorial();$('title').textContent='准备好了吗？';$('description').textContent='揭开所有安全方块即可通关。切换插旗模式，可以标记你怀疑的地雷。';$('primary').textContent='开始游戏'}else start()}else if(state==='won'&&!claimed)claim();else newRound()};$('secondary').onclick=()=>{if(state==='tutorial')start();else showDialog('玩法说明','金币数字代表周围 8 格中的地雷数量。\n\n揭开全部 44 个安全方块即可获胜。切换插旗模式，或用鼠标右键标记地雷。第一次点击始终安全。\n\n通关后可领取 440 模拟积分。',[['继续',()=>{}]])};$('reveal').onclick=()=>setMode('reveal');$('flag').onclick=()=>setMode('flag');$('dismiss').onclick=()=>$('dialog').close();$('menu').onclick=()=>showDialog('游戏菜单','6 × 9 棋盘 · 10 颗地雷\n通关可领取 440 模拟积分，不涉及真实资产。',[['新的一局',newRound],['重新查看教程',tutorial],['继续',()=>{}]]);$('close').onclick=returnToLobby;
setInterval(()=>{updateIdle();if(state==='playing'&&started&&!paused){seconds++;$('timer').textContent=`${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`}},1000);
let randomSeed=74;const rand=()=>{randomSeed=(randomSeed*16807)%2147483647;return(randomSeed-1)/2147483646};for(let i=0;i<185;i++){const s=document.createElement('i');s.className='star';const size=.12+rand()*.45;s.style.cssText=`left:${rand()*100}%;top:${rand()*100}%;width:${size}cqw;height:${size}cqw;opacity:${.1+rand()*.45}`;document.querySelector('.stars').append(s)}
tutorial();
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'read_game',description:'Read visible game status without exposing hidden mines.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({state,seconds,coins:state==='tutorial'||state==='lost'?0:board.filter(c=>c.revealed&&!c.mine).length*10,cells:board.map((c,i)=>({index:i,flagged:c.flagged,revealed:c.revealed,...(c.revealed?{neighboringMines:c.n,mine:c.mine}:{})}))})})}catch{}}
